#include <stdio.h>
/*
 * ex02：五段流水线的吞吐率 / 加速比 / 效率
 * 公式：
 *   理想总拍  = n + k - 1        （k 段流水线处理 n 条指令）
 *   实际总拍  = 理想总拍 + 停顿拍
 *   吞吐率 TP = n / 实际总拍
 *   加速比 S  = (n*k) / 实际总拍 = 顺序执行拍数 / 流水执行拍数
 *   效率   E  = S / k = n / 实际总拍
 * 注意：E 与 TP 数值相同只是「每拍 1 条」这个前提下的巧合，概念不同（E 是设备利用率）。
 */
int main(void) {
    int k = 5;        /* 流水段数：IF/ID/EX/MEM/WB */
    int n = 12;       /* 指令条数 */
    int stall = 4;    /* 因冒险插入的停顿拍 */

    int ideal = k + (n - 1);          /* 无停顿时的总拍数 */
    int total = ideal + stall;        /* 含停顿的实际总拍数 */

    double tp = (double)n / total;              /* 吞吐率：每拍完成多少条 */
    double s  = (double)(n * k) / total;        /* 加速比：顺序 n*k 拍 vs 流水 total 拍 */
    double e  = s / k;                          /* 效率：加速比 / 段数 */

    printf("五段流水线 处理 %d 条指令\n", n);
    printf("理想总拍(无停顿)=n+k-1=%d\n", ideal);
    printf("实际总拍(含%d停顿)=%d\n", stall, total);
    printf("吞吐率 TP=n/总拍=%.4f 指令/拍\n", tp);
    printf("加速比 S =n*k/总拍=%.4f\n", s);
    printf("效率   E =n/总拍  =%.4f (%.1f%%)\n", e, e * 100.0);
    return 0;
}
